mapper.update:
UPDATE daily_report_subscription SET support_purpose = #{purpose}, enabled = #{enabled},
    consent_at = CASE WHEN #{enabled} THEN #{now} ELSE consent_at END, updated_at = #{now}
WHERE account_id = #{accountId}

UPDATE daily_report_subscription SET verification_email = #{email}, verification_token_hash = #{hash},
    verification_expires_at = #{expiresAt}, verification_requested_at = #{now}, updated_at = #{now}
WHERE account_id = #{accountId}
    AND (verification_requested_at IS NULL OR verification_requested_at <= #{retryBefore})

UPDATE daily_report_subscription s JOIN daily_report r ON r.account_id = s.account_id
SET s.enabled = FALSE, s.updated_at = #{now}
WHERE r.unsubscribe_token_hash = #{hash}

UPDATE daily_report r SET r.status = 'FAILED', r.error_message = '생성이 중단되었습니다. 오늘 한 번만 다시 시도할 수 있습니다.'
WHERE r.status = 'GENERATING' AND r.started_at < #{before}
    AND NOT EXISTS (SELECT 1 FROM daily_report_generation_job j WHERE j.report_id = r.id AND j.generation_key = r.generation_key)

mapper.select:
SELECT id FROM daily_report_generation_job
WHERE status = 'QUEUED' AND next_publish_at <= #{now} AND deadline_at > #{now}
ORDER BY next_publish_at, id LIMIT 20

mapper.update:
UPDATE daily_report_generation_job j JOIN daily_report r ON r.id = j.report_id AND r.generation_key = j.generation_key
SET j.status = 'RUNNING', j.started_at = #{now}, r.started_at = #{now}
WHERE j.id = #{id} AND j.status = 'QUEUED' AND j.deadline_at > #{now}
    AND r.status = 'GENERATING' AND r.report_date = DATE(#{now})
